DROP TABLE IF EXISTS `schema_migrations`;
CREATE TABLE `schema_migrations` (`version` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL, `applied_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`version`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `import_batch` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `source` varchar(255) NULL DEFAULT '', `filename` varchar(512) NOT NULL DEFAULT '', `biz_date` date NOT NULL, `team` varchar(64) NULL DEFAULT '', `imported_rows` int NOT NULL DEFAULT '0', `ok_rows` int NOT NULL DEFAULT '0', `failed_rows` int NOT NULL DEFAULT '0', `note` text, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `idx_import_batch_date` (`biz_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `person` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(64) NOT NULL DEFAULT '', `gender` enum('male','female','unknown') NOT NULL DEFAULT 'unknown', `master_id` bigint unsigned DEFAULT NULL, `generation` int DEFAULT NULL, `group_name` varchar(64) DEFAULT NULL, `avatar_url` varchar(512) DEFAULT NULL, `hide_in_daily_report` tinyint(1) NOT NULL DEFAULT '0', `phone` varchar(32) DEFAULT NULL, `status` enum('active','left','paused') NOT NULL DEFAULT 'active', `joined_at` date DEFAULT NULL, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `deleted_at` datetime(3) DEFAULT NULL, PRIMARY KEY (`id`), KEY `idx_master` (`master_id`), KEY `idx_status_gender` (`status`,`gender`), KEY `idx_name` (`name`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `account` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `person_id` bigint unsigned NOT NULL, `anchor_id` varchar(128) NULL, `douyin_no` varchar(128) NULL DEFAULT '', `anchor_name` varchar(255) NULL DEFAULT '', `is_primary` tinyint(1) NOT NULL DEFAULT '0', `status` enum('active','disabled') NOT NULL DEFAULT 'active', `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_anchor` (`anchor_id`), KEY `idx_person` (`person_id`), KEY `idx_douyin_no` (`douyin_no`), KEY `idx_account_person_primary` (`person_id`,`is_primary`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `daily_metric` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `person_id` bigint unsigned NOT NULL, `anchor_id` varchar(128) NULL, `biz_date` date NOT NULL, `wave` bigint DEFAULT NULL, `cumulative_wave` bigint DEFAULT NULL, `prev_snapshot_date` date DEFAULT NULL, `wave_span` smallint DEFAULT NULL, `wave_reliable` tinyint(1) DEFAULT NULL, `minutes` int DEFAULT NULL, `cumulative_minutes` int DEFAULT NULL, `minutes_span` smallint DEFAULT NULL, `minutes_reliable` tinyint(1) DEFAULT NULL, `is_live` tinyint(1) DEFAULT NULL, `tier` char(1) DEFAULT NULL, `source_batch_id` bigint unsigned DEFAULT NULL, `recomputed_at` datetime(3) DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_person_date` (`person_id`,`biz_date`), KEY `idx_daily_date` (`biz_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `plans` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `title` varchar(128) NOT NULL, `metric` varchar(16) NOT NULL, `days` int NOT NULL DEFAULT '3', `payload` mediumtext NOT NULL, `created_at` varchar(40) NOT NULL, `published` tinyint(1) NOT NULL DEFAULT '0', `event_type` varchar(32) NOT NULL DEFAULT '', PRIMARY KEY (`id`), KEY `idx_plans_published` (`published`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `aliases` (`alias` varchar(64) NOT NULL, `real_name` varchar(64) NOT NULL DEFAULT '', PRIMARY KEY (`alias`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `my_accounts` (`name` varchar(64) NOT NULL, `phone` varchar(24) NOT NULL DEFAULT '', `pass` varchar(255) NOT NULL DEFAULT '', `is_admin` tinyint(1) NOT NULL DEFAULT '0', `created_at` varchar(40) NOT NULL, `bound` tinyint(1) NOT NULL DEFAULT '1', `bound_at` varchar(40) NOT NULL DEFAULT '', `source` varchar(16) NOT NULL DEFAULT 'admin', `wb_state` varchar(64) NOT NULL DEFAULT '', `person_id` bigint unsigned DEFAULT NULL, PRIMARY KEY (`name`), KEY `idx_my_accounts_person` (`person_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `bot_sessions` (`channel` varchar(16) NOT NULL, `conversation_id` varchar(64) NOT NULL, `kind` varchar(16) NOT NULL DEFAULT '', `last_text` text, `last_seen` varchar(40) NOT NULL DEFAULT '', `is_admin` tinyint(1) NOT NULL DEFAULT '0', PRIMARY KEY (`channel`,`conversation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `config` (`cfg_key` varchar(64) NOT NULL, `cfg_value` mediumtext NOT NULL, `updated_at` varchar(40) NOT NULL DEFAULT '', PRIMARY KEY (`cfg_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `roster_state` (`event_type` varchar(32) NOT NULL, `body` mediumtext NOT NULL, `updated_at` varchar(40) NOT NULL DEFAULT '', PRIMARY KEY (`event_type`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `push_bindings` (`name` varchar(64) NOT NULL, `team` varchar(16) NOT NULL DEFAULT '', `person_id` bigint unsigned NOT NULL DEFAULT '0', `conversation_id` varchar(64) NOT NULL DEFAULT '', `to_user_id` varchar(64) NOT NULL DEFAULT '', `nickname` varchar(64) NOT NULL DEFAULT '', `bind_code` varchar(16) NOT NULL DEFAULT '', `code_expires` varchar(40) NOT NULL DEFAULT '', `bound_at` varchar(40) NOT NULL DEFAULT '', `notify_target` tinyint(1) NOT NULL DEFAULT '0', `daily_report` tinyint(1) NOT NULL DEFAULT '0', `last_push` varchar(40) NOT NULL DEFAULT '', `last_error` varchar(255) NOT NULL DEFAULT '', `updated_at` varchar(40) NOT NULL DEFAULT '', `last_report_date` varchar(16) NOT NULL DEFAULT '', PRIMARY KEY (`name`), KEY `idx_push_code` (`bind_code`), KEY `idx_push_conv` (`conversation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `push_jobs` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `team` varchar(64) NULL DEFAULT '', `biz_date` varchar(16) NOT NULL DEFAULT '', `run_at` varchar(40) NOT NULL DEFAULT '', `status` varchar(16) NOT NULL DEFAULT 'pending', `created_at` varchar(40) NOT NULL DEFAULT '', `done_at` varchar(40) NOT NULL DEFAULT '', `note` text, PRIMARY KEY (`id`), KEY `idx_push_jobs_run` (`status`,`run_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `my_targets` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(64) NOT NULL, `team` varchar(16) NOT NULL DEFAULT '', `kind` varchar(24) NOT NULL, `target_person_id` bigint unsigned NOT NULL DEFAULT '0', `target_name` varchar(64) NOT NULL DEFAULT '', `target_value` bigint unsigned NOT NULL DEFAULT '0', `hit` tinyint(1) NOT NULL DEFAULT '0', `last_gap` bigint NOT NULL DEFAULT '0', `last_notice_date` varchar(16) NOT NULL DEFAULT '', `created_at` varchar(40) NOT NULL DEFAULT '', PRIMARY KEY (`id`), UNIQUE KEY `uk_my_target` (`name`,`team`,`kind`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `anchor_claims` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `person_id` bigint unsigned NOT NULL, `person_name` varchar(64) NOT NULL DEFAULT '', `team` varchar(16) NOT NULL DEFAULT '', `douyin_no` varchar(128) NULL DEFAULT '', `screenshot` longblob, `mime` varchar(128) NULL DEFAULT '', `status` varchar(16) NOT NULL DEFAULT 'pending', `reject_reason` varchar(255) NOT NULL DEFAULT '', `created_at` varchar(40) NOT NULL DEFAULT '', `decided_at` varchar(40) NOT NULL DEFAULT '', `decided_by` varchar(64) NOT NULL DEFAULT '', PRIMARY KEY (`id`), KEY `idx_claim_status` (`status`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `import_pending` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(64) NOT NULL, `douyin_no` varchar(128) NULL DEFAULT '', `biz_date` date NOT NULL, `wave` bigint DEFAULT NULL, `cumulative_wave` bigint DEFAULT NULL, `minutes` int DEFAULT NULL, `is_live` tinyint(1) DEFAULT NULL, `source_batch_id` bigint unsigned DEFAULT NULL, `absorbed_person_id` bigint unsigned DEFAULT NULL, `absorbed_at` datetime(3) DEFAULT NULL, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `idx_import_pending_date` (`biz_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `monthly_duration` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `person_id` bigint unsigned NOT NULL, `period` varchar(7) NOT NULL, `minutes` int NOT NULL DEFAULT '0', `source_batch_id` bigint unsigned DEFAULT NULL, `updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_monthly_duration` (`person_id`,`period`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `monthly_metric` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `person_id` bigint unsigned NOT NULL, `period` varchar(7) NOT NULL, `wave` bigint NOT NULL DEFAULT '0', `live_days` int NOT NULL DEFAULT '0', `best_day_wave` bigint NOT NULL DEFAULT '0', `best_day_date` date DEFAULT NULL, `source_batch_id` bigint unsigned DEFAULT NULL, `recomputed_at` datetime(3) DEFAULT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_monthly_metric` (`person_id`,`period`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `duration_snapshot` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `anchor_id` varchar(128) NULL, `biz_date` date NOT NULL, `minutes` int NOT NULL DEFAULT '0', `cumulative_minutes` int NOT NULL DEFAULT '0', `minutes_span` smallint NOT NULL DEFAULT '1', `minutes_reliable` tinyint(1) NOT NULL DEFAULT '1', `source_batch_id` bigint unsigned DEFAULT NULL, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_duration_snapshot` (`anchor_id`,`biz_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `wave_snapshot` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `anchor_id` varchar(128) NULL, `biz_date` date NOT NULL, `wave_value` bigint NOT NULL DEFAULT '0', `rank_in_guild` int DEFAULT NULL, `source_batch_id` bigint unsigned DEFAULT NULL, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_wave_snapshot` (`anchor_id`,`biz_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `my_bind_requests` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `name` varchar(64) NOT NULL, `person_id` bigint unsigned NOT NULL, `person_name` varchar(64) NOT NULL DEFAULT '', `team` varchar(16) NOT NULL DEFAULT '', `status` varchar(16) NOT NULL DEFAULT 'pending', `reason` varchar(255) NOT NULL DEFAULT '', `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `decided_at` datetime(3) DEFAULT NULL, `decided_by` varchar(64) NOT NULL DEFAULT '', PRIMARY KEY (`id`), KEY `idx_bind_requests_status` (`status`,`created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `access_logs` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `kind` varchar(64) NULL DEFAULT '', `ip` varbinary(40) DEFAULT NULL, `province` varchar(128) NULL DEFAULT '', `city` varchar(128) NULL DEFAULT '', `isp` varchar(128) NULL DEFAULT '', `geo_source` varchar(255) NULL DEFAULT '', `team` varchar(16) NOT NULL DEFAULT '', `path` varchar(1024) NOT NULL DEFAULT '', `account_name` varchar(128) NULL DEFAULT '', `allowed` tinyint(1) NOT NULL DEFAULT '0', `login_ok` tinyint(1) NOT NULL DEFAULT '0', `dedup_key` varchar(255) NULL DEFAULT '', `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `idx_access_logs_created` (`created_at`), KEY `idx_access_logs_dedup` (`dedup_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `ip_allowlist` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `ip` varchar(64) NOT NULL, `note` text NULL, `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `uk_ip_allowlist` (`ip`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `ip_geo_cache` (`ip` varbinary(40) NOT NULL, `province` varchar(128) NULL DEFAULT '', `city` varchar(128) NULL DEFAULT '', `isp` varchar(128) NULL DEFAULT '', `source` varchar(255) NULL DEFAULT '', `allowed` tinyint(1) NOT NULL DEFAULT '0', `looked_up_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`ip`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `identity_orphan_log` (`id` bigint unsigned NOT NULL AUTO_INCREMENT, `tbl` varchar(64) NOT NULL, `row_key` varchar(128) NOT NULL DEFAULT '', `person_id` bigint unsigned NOT NULL DEFAULT '0', `kind` varchar(64) NULL DEFAULT '', `detected_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `handled` tinyint(1) NOT NULL DEFAULT '0', `note` text, PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `wx_push_accounts` (`name` varchar(64) NOT NULL, `team` varchar(16) NOT NULL DEFAULT '', `person_id` bigint unsigned NOT NULL DEFAULT '0', `ilink_bot_id` varchar(64) NOT NULL DEFAULT '', `ilink_user_id` varchar(64) NOT NULL DEFAULT '', `bot_token` varchar(255) NOT NULL DEFAULT '', `base_url` varchar(255) NOT NULL DEFAULT '', `nickname` varchar(64) NOT NULL DEFAULT '', `conversation_id` varchar(64) NOT NULL DEFAULT '', `updates_buf` mediumtext, `bound_at` varchar(40) NOT NULL DEFAULT '', `updated_at` varchar(40) NOT NULL DEFAULT '', PRIMARY KEY (`name`), KEY `idx_wx_push_conv` (`conversation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `wx_sessions` (`conversation_id` varchar(64) NOT NULL, `to_user_id` varchar(64) NOT NULL DEFAULT '', `context_token` mediumtext, `nickname` varchar(64) NOT NULL DEFAULT '', PRIMARY KEY (`conversation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
